/* native HTML5 drag fallback (used by synthetic/automation drag events) */
function cleanupNativeDrag() {
  if (!nativeDrag) return;
  nativeDrag.classList.remove('is-native-dragging');
  nativeDrag = null;
}

lists.forEach((ul) => {
  const items = Array.from(ul.children).filter((el) => el.matches('li.disc-item'));
  items.forEach((li) => {
    li.draggable = true;
    li.addEventListener('dragstart', (e) => {
      if (drag && drag.active) { e.preventDefault(); return; }
      if (drag) cancelDrag();
      nativeDrag = li;
      li.classList.add('is-native-dragging');
      if (e.dataTransfer) {
        e.dataTransfer.effectAllowed = 'move';
        try { e.dataTransfer.setData('text/plain', li.textContent.trim()); } catch (_) {}
      }
    });
    li.addEventListener('dragend', () => {
      if (nativeDrag === li) cleanupNativeDrag();
    });
  });
  ul.addEventListener('dragover', (e) => {
    if (!nativeDrag || !ul.contains(nativeDrag)) return;
    e.preventDefault();
    if (e.dataTransfer) e.dataTransfer.dropEffect = 'move';
    const y = e.clientY;
    const targets = Array.from(ul.children).filter((el) => el.matches('li.disc-item') && el !== nativeDrag);
    let target = null;
    for (const item of targets) {
      const r = item.getBoundingClientRect();
      if (y < r.top + r.height / 2) { target = item; break; }
    }
    if (target) ul.insertBefore(nativeDrag, target);
    else ul.appendChild(nativeDrag);
  });
  ul.addEventListener('drop', (e) => {
    if (!nativeDrag) return;
    e.preventDefault();
    cleanupNativeDrag();
  });
});

