from html.parser import HTMLParser
class P(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True); self.stack=[]; self.errors=[]
    def handle_starttag(self,tag,attrs):
        if tag not in ('meta','link','br','img','input','hr','source','area','base','col','embed','param','track','wbr','path','circle','rect','stop','use'):
            self.stack.append(tag)
    def handle_startendtag(self,tag,attrs): pass
    def handle_endtag(self,tag):
        if tag in ('meta','link','br','img','input','hr','source','area','base','col','embed','param','track','wbr','path','circle','rect','stop','use'): return
        if not self.stack: self.errors.append(('extra close',tag)); return
        if self.stack[-1]==tag: self.stack.pop()
        else:
            # find
            if tag in self.stack:
                while self.stack and self.stack[-1]!=tag:
                    self.errors.append(('unclosed',self.stack.pop()))
                if self.stack: self.stack.pop()
            else: self.errors.append(('mismatch',tag,self.stack[-3:]))
p=P(); p.feed(open('index.html',encoding='utf-8').read())
print('errors',p.errors[:20], 'remaining',p.stack[-10:])
